local UI = {}

local WEBSITE_URL = "https://editorscripts.com"

local IS_MACOS = FuPLATFORM_MAC or false

-- ============================================================================
-- Platform Window Flags
-- ============================================================================

-- WindowFlags for dialogs. macOS needs a Tool window to float above Resolve
-- (Window = true does not float there); on Windows/Linux Tool windows get no
-- taskbar entry and a non-standard frame, so use a regular window.
function UI.getDialogFlags()
    if IS_MACOS then
        return { Tool = true }
    end
    return { Window = true }
end

-- Call after AddWindow: keeps macOS Tool windows floating above Resolve.
-- No-op on other platforms (regular windows manage their own stacking).
function UI.applyDialogPlatformAttributes(win)
    if IS_MACOS then
        win:SetAttribute('WA_MacAlwaysShowToolWindow', true)
    end
end

-- ============================================================================
-- Explicit Dialog Centering
-- ============================================================================
-- Framed windows auto-center with a broken x coordinate when Resolve is on a
-- secondary display (measured on Resolve 21, macOS).
-- Frameless windows auto-center correctly everywhere, so a tiny frameless
-- probe window is used as the screen-center oracle: Show() positions a window
-- synchronously (Pos() is final before any RunLoop) but painting needs event
-- loop iterations that never happen between Show and Hide - the probe is
-- invisible. The real dialog is then Moved to the discovered center before
-- its own Show(); an explicit pre-Show Move sticks (auto-centering does not
-- override it).

local cachedAutoCenter = nil   -- {x, y} once probed; false = probe failed

-- Returns the true auto-center point {x, y} of the display Resolve is on, in
-- global Qt coordinates (primary display top-left origin, y-down), nil.
-- Returns nil, err on failure. Cached for the lifetime of the script run.
function UI.getAutoCenterPoint(ui, dispatcher)
    if cachedAutoCenter then return cachedAutoCenter, nil end
    if cachedAutoCenter == false then return nil, "center probe failed earlier this run" end

    local PROBE = 32
    local flags = IS_MACOS and { FramelessWindowHint = true, Tool = true }
                           or { FramelessWindowHint = true, Window = true }

    local ok, err = pcall(function()
        local probe = dispatcher:AddWindow({
            ID = 'CenterProbe',
            WindowFlags = flags,
        }, ui:VGroup{
            ID = 'CenterProbeRoot',
            MinimumSize = {PROBE, PROBE},
            MaximumSize = {PROBE, PROBE},
        })
        UI.applyDialogPlatformAttributes(probe)
        pcall(function() probe:SetAttribute('WA_ShowWithoutActivating', true) end)
        probe:Resize({PROBE, PROBE})
        probe:RecalcLayout()
        probe:Show()
        local pos = probe:Pos()
        local size = probe:Size()
        probe:Hide()

        -- Actual Size() read-back self-corrects any Qt minimum-size clamping
        local px, py = tonumber(pos and pos[1]), tonumber(pos and pos[2])
        local pw, ph = tonumber(size and size[1]), tonumber(size and size[2])
        if not (px and py and pw and ph) then
            error("probe Pos()/Size() read-back unusable")
        end
        local cx = px + pw / 2
        local cy = py + ph / 2
        if math.abs(cx) > 100000 or math.abs(cy) > 100000 then
            error("probe center implausible: " .. cx .. "," .. cy)
        end
        cachedAutoCenter = {x = cx, y = cy}
    end)

    if not ok then
        cachedAutoCenter = false
        -- Printed once per run (subsequent calls short-circuit on the cache)
        print("[WARN] Dialog centering probe failed - falling back to auto-centering ("
            .. tostring(err) .. ")")
        return nil, "center probe failed: " .. tostring(err)
    end
    return cachedAutoCenter, nil
end

-- Centers a dialog on the display Resolve is on. Call AFTER the final size is
-- set (fitDialogHeight or explicit Resize + RecalcLayout) and BEFORE Show().
-- Never call it on a visible window - resizing in place is fine, moving a
-- window under the user is not. On any failure it does nothing and returns
-- nil, err; the dialog then falls back to implicit auto-centering (correct on
-- the primary display, far-left on secondary displays).
-- Returns the applied position {x, y}, nil on success.
function UI.centerDialogOnScreen(win, ui, dispatcher)
    local center, err = UI.getAutoCenterPoint(ui, dispatcher)
    if not center then
        return nil, err
    end

    local ok, result = pcall(function()
        local size = win:Size()   -- frame-inclusive; pairs with Move/Pos coords
        local w, h = tonumber(size and size[1]), tonumber(size and size[2])
        if not (w and h) then
            error("win:Size() read-back unusable")
        end
        -- Implausible pre-Show sizes (never-laid-out window) must not produce
        -- a wrong Move; skipping falls back to implicit auto-centering
        if w < 100 or w > 4000 or h < 60 or h > 4000 then
            error("win:Size() implausible pre-Show: " .. w .. "x" .. h)
        end
        local x = math.floor(center.x - w / 2 + 0.5)
        local y = math.floor(center.y - h / 2 + 0.5)
        win:Move({x, y})
        return {x = x, y = y}
    end)

    if not ok then
        return nil, "centerDialogOnScreen failed: " .. tostring(result)
    end
    return result, nil
end

