-- ============================================================================
-- THEME RESOLUTION & STYLE BUILDING
-- ============================================================================
-- Module dependencies - injected by the ResolveKit facade.
UI._openURL = nil
UI._resolveTheme = nil   -- () -> "gray"|"blue"; composed by the facade
                         -- (user_preferences.json override, then file detection)

function UI._injectDependencies(openURL, resolveTheme)
    UI._openURL = openURL
    UI._resolveTheme = resolveTheme
end

local resolvedTheme, resolvedColors, resolvedStyles

-- Resolve the active palette once, lazily (after the facade has injected the
-- theme resolver). Falls back to gray if anything goes wrong.
local function getColors()
    if resolvedColors then return resolvedColors end
    resolvedTheme = "gray"
    if UI._resolveTheme then
        local ok, t = pcall(UI._resolveTheme)
        if ok and THEMES[t] then resolvedTheme = t end
    end
    resolvedColors = THEMES[resolvedTheme]
    return resolvedColors
end

-- Substitute {key} placeholders from the active palette. Unknown keys are left
-- as visible "{key}" text in the rendered UI - deliberate, makes typos obvious.
local function fmt(template)
    return (template:gsub("{(%w+)}", getColors()))
end

