-- ============================================================================
-- UI FUNCTIONS
-- ============================================================================

-- Prompt user for output directory using system dialog
function UI.promptForOutputDirectory(fusion)
    local path = fusion:RequestDir()

    if not path or path == "" then
        return nil, "No directory selected"
    end

    -- Remove trailing slash if present
    if path:sub(-1) == "/" or path:sub(-1) == "\\" then
        path = path:sub(1, -2)
    end

    return path, nil
end

-- ============================================================================
-- DIALOG BUILDERS
-- ============================================================================

-- Show status dialog with icon and message
-- Parameters:
--   ui - UIManager instance
--   dispatcher - UIDispatcher instance
--   options - {
--     title: Window title (optional, defaults based on icon)
--     message: Main message text
--     icon: 'success'|'warning'|'error'|'info' (default: 'info')
--   }
function UI.showStatusDialog(ui, dispatcher, options)
    options = options or {}

    local C, S = getColors(), getStyles()

    local icons = {
        success = successIcon,
        warning = warningIcon,
        error   = failureIcon,
        info    = failureIcon,
    }

    local titles = {
        success = 'Success',
        warning = 'Warning',
        error   = 'Error',
        info    = 'Information',
    }

    local iconType = options.icon or 'info'
    local iconFn = icons[iconType] or failureIcon
    local statusTitle = options.title or titles[iconType] or 'Notice'
    local statusMessage = options.message or ""

    -- Buttons: default to a single OK that returns nil (back-compat). Callers can
    -- pass a vertical stack of {id, text, value, style} and get the clicked value.
    local buttons = options.buttons or {{ id = 'OkButton', text = 'OK', value = nil, style = 'primary' }}

    local DIALOG_PADDING = 28
    local DIALOG_WIDTH = 320
    local CONTENT_WIDTH = DIALOG_WIDTH - (DIALOG_PADDING * 2)
    local ICON_SIZE = {CONTENT_WIDTH, 70}

    -- Estimate message height from content to auto-size the dialog. Slightly
    -- conservative (wider CHAR_WIDTH, taller LINE_HEIGHT) so the WordWrap label
    -- is allocated enough room and the final line never clips.
    local function estimateMessageHeight(message, width)
        local CHAR_WIDTH = 6.5
        local LINE_HEIGHT = 15
        local charsPerLine = math.floor(width / CHAR_WIDTH)
        local totalLines = 0
        for segment in (message .. "\n"):gmatch("(.-)\n") do
            totalLines = totalLines + math.max(1, math.ceil(#segment / charsPerLine))
        end
        return totalLines * LINE_HEIGHT
    end

    -- Base height covers padding + icon + gaps + title + one button; each extra
    -- stacked button adds its 44px height + 8px gap + ~4px of rendered slack so
    -- the bottom button never clips as the stack grows. The min/max clamp scales
    -- with the stack too, so short-message multi-button dialogs still fit.
    local PER_BUTTON = 56
    -- 230 base (not 224): the extra ~6px keeps the button off the bottom edge in
    -- the long-message branch, where height lands exactly on FIXED + message and
    -- gets no slack from the MIN_HEIGHT floor.
    local FIXED_HEIGHT = 230 + (#buttons - 1) * PER_BUTTON
    local messageHeight = estimateMessageHeight(statusMessage, CONTENT_WIDTH)
    local MIN_HEIGHT = 260 + (#buttons - 1) * PER_BUTTON
    local MAX_HEIGHT = 500 + (#buttons - 1) * PER_BUTTON
    local DIALOG_HEIGHT = math.max(MIN_HEIGHT, math.min(MAX_HEIGHT, FIXED_HEIGHT + messageHeight))

    -- Build the content column, then append the vertical button stack.
    local content = {
        Weight = 1,
        Spacing = 0,

        ui:VGap(DIALOG_PADDING),

        -- Icon
        ui:Label{
            ID = 'IconLabel',
            Text = iconFn(),
            MinimumSize = ICON_SIZE,
            MaximumSize = ICON_SIZE,
            Weight = 0,
            StyleSheet = S.STATUS_ICON,
        },

        ui:VGap(24),

        -- Title
        ui:Label{
            ID = 'TitleLabel',
            Text = statusTitle,
            Alignment = { AlignHCenter = true },
            Font = ui:Font{ PixelSize = 20 },
            Weight = 0,
            StyleSheet = "font-weight: 600; color: " .. C.statusText .. ";",
        },

        ui:VGap(12),

        -- Message. WordWrap only wraps a long unbroken line if the label is
        -- given vertical room — without a MinimumSize it collapses to one line
        -- and clips. Allocate the estimated wrapped height.
        ui:Label{
            ID = 'MessageLabel',
            Text = statusMessage,
            Alignment = { AlignHCenter = true, AlignVCenter = true },
            Font = ui:Font{ PixelSize = 12 },
            Weight = 0,
            WordWrap = true,
            MinimumSize = {0, messageHeight},
            StyleSheet = "color: " .. C.statusTextDim .. ";",
        },

        ui:VGap(20),
    }

    for i, btn in ipairs(buttons) do
        if i > 1 then table.insert(content, ui:VGap(8)) end
        table.insert(content, ui:HGroup{
            Weight = 0,
            Spacing = 0,
            ui:Button{
                ID = btn.id,
                Text = btn.text,
                Weight = 1,
                MinimumSize = {0, 44},
                StyleSheet = btn.style == 'secondary' and S.STATUS_BUTTON_SECONDARY or S.STATUS_BUTTON,
            },
        })
    end

    table.insert(content, ui:VGap(DIALOG_PADDING))

    local win = dispatcher:AddWindow({
        ID = 'StatusDialog',
        WindowTitle = statusTitle,
        StyleSheet = "* { background-color: " .. C.dialogBg .. "; color: " .. C.statusText .. "; }",
        WindowFlags = UI.getDialogFlags(),
    }, ui:VGroup{
        ID = 'root',
        MinimumSize = {DIALOG_WIDTH, DIALOG_HEIGHT},
        MaximumSize = {DIALOG_WIDTH, DIALOG_HEIGHT},
        Spacing = 0,

        ui:HGroup{
            Spacing = 0,
            Weight = 1,
            ui:HGap(DIALOG_PADDING),

            ui:VGroup(content),

            ui:HGap(DIALOG_PADDING),
        },
    })

    UI.applyDialogPlatformAttributes(win)

    local result = options.closeValue

    for _, btn in ipairs(buttons) do
        win.On[btn.id].Clicked = function(ev)
            result = btn.value
            dispatcher:ExitLoop()
        end
    end

    function win.On.StatusDialog.Close(ev)
        result = options.closeValue
        dispatcher:ExitLoop()
    end

    win:RecalcLayout()
    UI.centerDialogOnScreen(win, ui, dispatcher)
    win:Show()
    dispatcher:RunLoop()
    win:Hide()

    return result
end

-- Convenience wrapper: Show success dialog
function UI.showSuccessDialog(ui, dispatcher, message, title)
    UI.showStatusDialog(ui, dispatcher, {
        title = title,
        message = message,
        icon = 'success'
    })
end

-- Convenience wrapper: Show error dialog
function UI.showErrorDialog(ui, dispatcher, message, title)
    UI.showStatusDialog(ui, dispatcher, {
        title = title,
        message = message,
        icon = 'error'
    })
end

-- Convenience wrapper: Show warning dialog
function UI.showWarningDialog(ui, dispatcher, message, title)
    UI.showStatusDialog(ui, dispatcher, {
        title = title,
        message = message,
        icon = 'warning'
    })
end

