--- Creates a reusable footer element for script dialogs
-- @param ui Fusion UIManager instance
-- @param options Table with footer options:
--   - scriptName (string): Display name for the script
--   - version (string): Version number (e.g., "0.1.0")
--   - linkText (string, optional): Text for the link button (default: "EditorScripts")
--   - padding (number, optional): Left/right padding in pixels (default: 28)
-- @return VGroup UI element
-- @note Call utils.attachFooterHandler(dialog) after dialog creation to wire up the website link
-- @note The footer owns the gap to the window's bottom edge, tuned so it looks
--       identical to the divider-to-text gap. Scripts must never add their own
--       gap below the footer; instead place a ui:VGap(0, 1) stretch immediately
--       before the footer so it stays pinned to the bottom.
function UI.createFooter(ui, options)
    options = options or {}
    local scriptName = options.scriptName or "Script"
    local version = options.version or "1.0.0"
    local linkText = options.linkText or "EditorScripts"
    local padding = options.padding or 28
    local textGap = 2    -- divider line to text row
    local bottomGap = 8  -- text row to window edge: structurally larger than textGap
                         -- because the label's font box has more dead space above the
                         -- glyphs than below; 8 reads as the same visual gap as textGap

    local C = getColors()

    return ui:VGroup{
        ID = "FooterSection",
        Weight = 0,
        Spacing = 0,

        -- Full-width divider line
        ui:Label{
            Weight = 0,
            MinimumSize = {0, 1},
            MaximumSize = {16777215, 1},
            StyleSheet = "background-color: " .. C.divider .. ";",
        },

        ui:VGap(textGap),

        -- Footer content with padding
        ui:HGroup{
            ID = "Footer",
            Weight = 0,
            Spacing = 0,
            ui:HGap(padding),
            -- Left side: Script Name + Version (dimmed)
            ui:Label{
                Text = scriptName .. "  ",
                Weight = 0,
                StyleSheet = "color: " .. C.textMuted .. "; font-size: 10px;",
            },
            ui:Label{
                Text = "v" .. version,
                Weight = 0,
                StyleSheet = "color: " .. C.versionGhost .. "; font-size: 10px;",
            },
            -- Spacer
            ui:Label{ Weight = 1 },
            -- Right side: Website link button
            ui:Button{
                ID = "FooterWebsiteLink",
                Text = linkText,
                Weight = 0,
                Flat = true,
                StyleSheet = "QPushButton { color: " .. C.textMuted .. "; font-size: 10px; background: transparent; border: none; }"
                    .. " QPushButton:hover { color: " .. C.textMutedHover .. "; text-decoration: underline; }",
            },
            ui:HGap(padding),
        },

        -- Bottom-edge gap: must visually mirror the divider-to-text gap above
        ui:VGap(bottomGap),
    }
end

--- Attaches the footer website link click handler to a dialog or window
-- @param dialogOrWin The dialog or window object returned by disp:AddWindow()
function UI.attachFooterHandler(dialogOrWin)
    function dialogOrWin.On.FooterWebsiteLink.Clicked(ev)
        if UI._openURL then UI._openURL(WEBSITE_URL) end
    end
end

-- Window frame delta: win:Resize takes the frame-inclusive OUTER size while
-- fitted heights are in client coordinates. Resizing to the bare client size
-- briefly renders a visible window ~20px too narrow before the fixed-size lock
-- corrects it (a visible flash), so resizes must include this delta to land on
-- the final geometry in one step. Measured at runtime as win:Size() minus
-- root:Size() while the previous lock still holds, so each platform's actual
-- frame is used; if the readings are stale or unusable (e.g. first call on a
-- fresh, not-yet-visible window) the delta stays 0.
local function computeDialogFrameDelta(win, root)
    local deltaW, deltaH = 0, 0
    if not root then return deltaW, deltaH end
    local okW, wSize = pcall(function() return win:Size() end)
    local okR, rSize = pcall(function() return root:Size() end)
    if okW and okR and type(wSize) == "table" and type(rSize) == "table" then
        local ww, wh = tonumber(wSize[1]), tonumber(wSize[2])
        local rw, rh = tonumber(rSize[1]), tonumber(rSize[2])
        if ww and rw and rw > 0 and ww >= rw and (ww - rw) <= 100 then
            deltaW = ww - rw
        end
        if wh and rh and rh > 0 and wh >= rh and (wh - rh) <= 100 then
            deltaH = wh - rh
        end
    end
    return deltaW, deltaH
end

--- Sizes a dialog window to exactly fit its content height (footer flush at the bottom).
-- Requires the standard dialog skeleton: root VGroup pinned to a fixed WIDTH only
-- (MinimumSize = {w, 0}, MaximumSize = {w, 16777215} -- NOT a fixed height), a
-- ui:VGap(0, 1) stretch between MainContent and the footer, and createFooter last.
--
-- How it works: because MainContent and FooterSection are Weight 0 and the stretch
-- absorbs all surplus, both always render at their NATURAL height whenever the
-- window is at least that tall (verified live on macOS, Resolve 21: they read the
-- same regardless of window size). So the exact window height is simply
-- MainContent height + FooterSection height, read back via Size(). Do not derive
-- the height from the window's own minimum-size clamp instead: Qt updates that
-- minimum lazily after a Hidden flip, so a collapse measured against it shrinks
-- only partially. And do not use win:Size() as ground truth either - it includes
-- the window frame (~+20px); element sizes are in client coordinates.
--
-- After fitting, the root DialogContent group is LOCKED to the fitted size
-- (Min == Max on both axes). This makes the window non-user-resizable AND is
-- what actually enforces the width: with only a width minimum, the window can
-- open ~20px narrower than intended (win:Resize sets the OUTER size and the
-- minimum is enforced lazily); with Min == Max the client width comes out
-- exactly right (verified live, macOS Resolve 21). The lock is lifted at the
-- start of every call, so re-fitting after a section toggle still works.
--
-- Call BEFORE win:Show() so the height is defined at open time (needed both for
-- correct first-frame layout and so UI.centerDialogOnScreen measures the final
-- size). Call again after toggling a section's Hidden flag to both grow AND
-- shrink the window (RecalcLayout alone can only grow it) - but do NOT re-center
-- on a re-fit, the window is already visible.
-- @param win Window object returned by disp:AddWindow()
-- @param width number Dialog width in px (same value the root VGroup is pinned to)
-- @return number|nil Fitted content height in px, or nil on failure
-- @return string|nil Error message on failure (caller should fall back to a fixed height)
function UI.fitDialogHeight(win, width)
    if not win or not width then
        return nil, "fitDialogHeight requires a window and a width"
    end

    local mainContent = win:Find("MainContent")
    local footer = win:Find("FooterSection")
    if not mainContent or not footer then
        return nil, "Dialog is missing the standard MainContent/FooterSection skeleton"
    end
    local root = win:Find("DialogContent")

    local deltaW, deltaH = computeDialogFrameDelta(win, root)

    -- Lift a previous call's fixed-size lock so this measurement sees the
    -- content's new natural height
    if root then
        root.MinimumSize = {width, 0}
        root.MaximumSize = {width, 16777215}
    end

    local function measure()
        local okM, mSize = pcall(function() return mainContent:Size() end)
        local okF, fSize = pcall(function() return footer:Size() end)
        if not okM or not okF or type(mSize) ~= "table" or type(fSize) ~= "table" then
            return nil
        end
        local mH, fH = tonumber(mSize[2]), tonumber(fSize[2])
        if not mH or not fH or mH <= 0 or fH <= 0 then return nil end
        return mH + fH
    end

    -- Flush pending layout changes (e.g. a section's Hidden flip) before measuring
    win:RecalcLayout()
    local height = measure()
    if not height then
        return nil, "Geometry read-back failed"
    end

    -- Converge: if the window was too SMALL before this call (e.g. a section was
    -- just expanded), content was compressed and the first measurement is short;
    -- once resized it re-expands, so re-measure until stable (1-2 passes typical)
    for _ = 1, 3 do
        win:Resize({width + deltaW, height + deltaH})
        win:RecalcLayout()
        local remeasured = measure()
        if not remeasured or math.abs(remeasured - height) <= 1 then
            break
        end
        height = remeasured
    end

    -- Lock to the fitted size: Min == Max enforces the exact client width and
    -- makes the window non-user-resizable
    if root then
        root.MinimumSize = {width, height}
        root.MaximumSize = {width, height}
        win:Resize({width + deltaW, height + deltaH})
        win:RecalcLayout()
    end

    return height
end

--- Pre-lays-out collapsed dialog sections while the window is still hidden.
-- Call BEFORE win:Show(). Widgets that have never been laid out paint their
-- first visible frame at unpositioned coordinates (top-left of the window)
-- before the layout pass places them; showing them once while the window is
-- invisible gives them real geometry, so the first user-triggered reveal is
-- clean. It also gives toggleDialogSections real sizes to predict from on the
-- first toggle.
-- @param win Window object returned by disp:AddWindow()
-- @param elements Array of section elements (no nil holes); only currently
--        hidden ones are touched, and their Hidden state is restored
function UI.prewarmDialogSections(win, elements)
    if not win or type(elements) ~= "table" then return end
    local warmed = {}
    for _, el in ipairs(elements) do
        if el then
            local ok, hidden = pcall(function() return el.Hidden end)
            if ok and hidden then
                el.Hidden = false
                table.insert(warmed, el)
            end
        end
    end
    if #warmed == 0 then return end
    win:RecalcLayout()
    for _, el in ipairs(warmed) do
        el.Hidden = true
    end
    win:RecalcLayout()
end

--- Toggles the visibility of one or more dialog sections and refits the window
-- in a single repaint where possible. Flipping Hidden and then measuring forces
-- an intermediate layout pass that paints one wrong-sized frame (window still
-- at the old height); this helper predicts the post-toggle height from the
-- sections' own last laid-out heights, applies the flips and the resize
-- together, then runs fitDialogHeight as a convergence pass - geometry-neutral
-- (no repaint) when the prediction is exact. Call prewarmDialogSections before
-- win:Show() so never-shown sections have real sizes to predict from.
-- @param win Window object returned by disp:AddWindow()
-- @param width number Dialog width in px (same value the root VGroup is pinned to)
-- @param sections Array of {element = <element>, hidden = <boolean>} entries
-- @return number|nil Fitted content height in px, or nil on failure
-- @return string|nil Error message on failure (caller should fall back to a fixed height)
function UI.toggleDialogSections(win, width, sections)
    if not win or not width or type(sections) ~= "table" then
        return nil, "toggleDialogSections requires a window, width, and sections list"
    end

    local root = win:Find("DialogContent")

    -- Prediction baseline: the current client height
    local predicted = nil
    if root then
        local ok, rSize = pcall(function() return root:Size() end)
        local rh = ok and type(rSize) == "table" and tonumber(rSize[2]) or nil
        if rh and rh > 0 then predicted = rh end
    end

    local anyChange = false
    for _, s in ipairs(sections) do
        local el = s and s.element
        if el then
            local wantHidden = s.hidden and true or false
            local okH, curHidden = pcall(function() return el.Hidden end)
            if okH then
                curHidden = curHidden and true or false
            else
                curHidden = not wantHidden  -- unknown state: assume it changes
            end
            if curHidden ~= wantHidden then
                anyChange = true
                if predicted then
                    local okS, elSize = pcall(function() return el:Size() end)
                    local elH = okS and type(elSize) == "table" and tonumber(elSize[2]) or nil
                    if elH and elH > 0 then
                        predicted = predicted + (wantHidden and -elH or elH)
                    else
                        predicted = nil  -- unmeasurable: fall through to plain fit
                    end
                end
                el.Hidden = wantHidden
            end
        end
    end

    if anyChange and root and predicted and predicted > 0 then
        -- Land the flips and the resize in the same layout pass
        local deltaW, deltaH = computeDialogFrameDelta(win, root)
        root.MinimumSize = {width, predicted}
        root.MaximumSize = {width, predicted}
        win:Resize({width + deltaW, predicted + deltaH})
        win:RecalcLayout()
    end

    -- Converge to the exact height (prediction can be off by inter-element
    -- spacing at most); also re-applies the fixed-size lock
    return UI.fitDialogHeight(win, width)
end

-- ============================================================================
-- PROGRESS WINDOW
-- ============================================================================

-- Event pump for cancellable progress windows.
-- dispatcher:StepLoop(false) processes ONE queued UI event without blocking.
-- It is undocumented and may be absent on some Resolve builds, so existence
-- is probed once (gating the Cancel button layout) and every invocation is
-- pcall-guarded (a runtime failure permanently degrades to "no cancel" with
-- a single [WARN]).
-- WARNING: pumping delivers ANY queued event, not just the Cancel click -
-- e.g. a queued main-dialog Close fires DURING processing instead of after
-- it. Close handlers must therefore stay teardown-only (save prefs /
-- ExitLoop), which all current dialogs honor. Cancel handlers must never
-- call ExitLoop (that would flag the persistent main dialog's RunLoop to
-- exit) and never call progress.update() (they already run inside its pump).
local stepLoopSupported = nil   -- nil = unprobed; true/false once known
local warnedPumpUnavailable = false

local function probeStepLoop(dispatcher)
    if stepLoopSupported == nil then
        local ok, fn = pcall(function() return dispatcher.StepLoop end)
        stepLoopSupported = ok and type(fn) == "function"
    end
    return stepLoopSupported
end

-- Drain up to n queued events (default 3: press/release/click headroom -
-- keep small, each call is an IPC round-trip).
-- Returns true while StepLoop keeps working, false once support is lost.
local function pumpEvents(dispatcher, n)
    if not stepLoopSupported then return false end
    for _ = 1, (n or 3) do
        local ok = pcall(function() dispatcher:StepLoop(false) end)
        if not ok then
            stepLoopSupported = false
            if not warnedPumpUnavailable then
                warnedPumpUnavailable = true
                print("[WARN] Cancel disabled - UIDispatcher:StepLoop() failed on this Resolve build")
            end
            return false
        end
    end
    return true
end

-- Create a progress window for batch operations
-- Returns a table with methods: show(), update(), hide(), isCancelled()
--
-- Parameters:
--   ui - UIManager instance
--   dispatcher - UIDispatcher instance
--   options - {
--     title: Window title (default: "Processing...")
--     totalItems: Total number of items to process
--     width: Window width (default: 400)
--     height: Window height (default: 160, or 210 when cancellable)
--     cancellable: Add a Cancel button (default: false). The batch loop MUST
--                  poll isCancelled() and break when it returns true - the
--                  button only requests cancellation, it cannot stop the
--                  loop by itself. Needs dispatcher:StepLoop(); without it
--                  the button is omitted and isCancelled() is always false.
--   }
--
-- Usage:
--   local progress = UI.createProgressWindow(ui, dispatcher, {
--       title = "Processing Timelines",
--       totalItems = #timelines,
--       cancellable = true,
--   })
--
--   progress.show()
--
--   for i, item in ipairs(items) do
--       if progress.isCancelled() then break end
--       progress.update(i, item.name, "Processing...")
--       -- do work
--   end
--
--   progress.update(#items, "Complete!", "Complete: all done", true)
--   utils.sleep(1)
--   progress.hide()
function UI.createProgressWindow(ui, dispatcher, options)
    options = options or {}
    local title = options.title or "Processing..."
    local totalItems = options.totalItems or 0
    local cancelEnabled = false
    if options.cancellable then
        -- Existence-only probe: do NOT invoke StepLoop here - an early call
        -- could dispatch a stale queued event before the window even shows
        cancelEnabled = probeStepLoop(dispatcher)
        if not cancelEnabled and not warnedPumpUnavailable then
            warnedPumpUnavailable = true
            print("[WARN] Cancel button unavailable - this Resolve build lacks UIDispatcher:StepLoop()")
        end
    end
    local width = options.width or 400
    local height = options.height or (cancelEnabled and 210 or 160)

    local C = getColors()
    local S = getStyles()

    -- Children built as a list so the Cancel row is appended only when
    -- enabled (never via the `elem or gap` trick - see the gap-axis rule)
    local children = {
        ID = 'root',

        ui:VGap(15),

        -- Header
        ui:Label{
            ID = 'HeaderLabel',
            Text = 'Processing...',
            Weight = 0,
            Font = ui:Font{PixelSize = 14, StyleName = 'Bold'},
            Alignment = {AlignHCenter = true},
            StyleSheet = "color: " .. C.textBright .. ";",
        },

        ui:VGap(10),

        -- Current item name
        ui:Label{
            ID = 'CurrentItemLabel',
            Text = 'Initializing...',
            Weight = 0,
            Font = ui:Font{PixelSize = 11},
            Alignment = {AlignHCenter = true},
            StyleSheet = "color: " .. C.textDim .. ";",
        },

        ui:VGap(10),

        -- Progress bar (using block characters)
        ui:Label{
            ID = 'ProgressBarLabel',
            Text = '░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░░',
            Weight = 0,
            Font = ui:Font{Family = 'Courier', PixelSize = 10},
            Alignment = {AlignHCenter = true},
            StyleSheet = "color: " .. C.accentProgress .. ";",
        },

        ui:VGap(6),

        -- Progress percentage and count
        ui:Label{
            ID = 'ProgressTextLabel',
            Text = '0% (0 / ' .. totalItems .. ')',
            Weight = 0,
            Font = ui:Font{PixelSize = 10},
            Alignment = {AlignHCenter = true},
            StyleSheet = "color: " .. C.textFaint .. ";",
        },
    }

    if cancelEnabled then
        table.insert(children, ui:VGap(10))
        table.insert(children, ui:HGroup{
            Weight = 0,

            ui:HGap(0, 1),

            ui:Button{
                ID = 'ProgressCancelButton',
                Text = 'Cancel',
                Weight = 0,
                MinimumSize = {100, 30},
                StyleSheet = S.BUTTON_SECONDARY,
            },

            ui:HGap(0, 1),
        })
    end

    table.insert(children, ui:VGap(15))

    -- Create window with consistent styling
    local win = dispatcher:AddWindow({
        ID = 'ProgressWindow',
        WindowTitle = title,
        WindowFlags = UI.getDialogFlags(),
        StyleSheet = "* { background-color: " .. C.windowBg .. "; color: " .. C.textBody .. "; }",
    }, ui:VGroup(children))

    UI.applyDialogPlatformAttributes(win)

    -- Cancel state lives in this closure - one flag per window instance
    local cancelRequested = false
    local pumpBroken = false     -- StepLoop existed but failed at runtime

    if cancelEnabled then
        -- Runs inside pumpEvents (i.e. inside progress.update). Must stay
        -- minimal: no ExitLoop, no update() - see the pump helper comment
        function win.On.ProgressCancelButton.Clicked(ev)
            if cancelRequested then return end
            cancelRequested = true
            local itm = win:GetItems()
            itm.ProgressCancelButton.Enabled = false
            itm.ProgressCancelButton.Text = 'Cancelling...'
        end

        -- X on the progress window = cancel request (the window hides; the
        -- batch stops between items and finalization still runs)
        function win.On.ProgressWindow.Close(ev)
            cancelRequested = true
        end
    end

    -- Create progress object with methods
    local progressObj = {
        window = win,
        totalItems = totalItems,
        isVisible = false
    }

    -- Show the window
    function progressObj.show()
        if progressObj.window and not progressObj.isVisible then
            progressObj.window:Resize({width, height})
            progressObj.window:RecalcLayout()
            UI.centerDialogOnScreen(progressObj.window, ui, dispatcher)
            progressObj.window:Show()
            progressObj.isVisible = true
        end
    end

    -- Update progress
    -- Parameters:
    --   current: Current item number (1-indexed)
    --   itemName: Name of current item being processed
    --   statusMessage: Optional status message (logged to console only, not shown in UI)
    --   isComplete: Optional boolean to indicate completion
    function progressObj.update(current, itemName, statusMessage, isComplete)
        if not progressObj.window then return end

        -- Pump queued events FIRST: a pending Cancel click runs its handler
        -- here, so the flag is already set when this update paints below
        if cancelEnabled and not pumpBroken then
            if not pumpEvents(dispatcher, 3) then
                pumpBroken = true
                local deadBtn = progressObj.window:GetItems().ProgressCancelButton
                if deadBtn then deadBtn.Enabled = false end
            end
        end

        local itm = progressObj.window:GetItems()
        local total = progressObj.totalItems

        -- Calculate percentage
        local percentage = total > 0 and math.floor((current / total) * 100) or 0

        -- Create progress bar (40 characters wide)
        local barWidth = 40
        local filledBlocks = total > 0 and math.floor((current / total) * barWidth) or 0
        local emptyBlocks = barWidth - filledBlocks
        local progressBar = string.rep('█', filledBlocks) .. string.rep('░', emptyBlocks)

        -- Update UI elements
        if isComplete then
            if cancelRequested and current < total then
                -- Cancelled part-way: neutral grey bar, honest count
                itm.HeaderLabel.Text = 'Cancelled'
                itm.CurrentItemLabel.Text = string.format('Processed %d of %d item%s',
                    current, total, total == 1 and '' or 's')
                itm.ProgressBarLabel.StyleSheet = "color: " .. C.textDim .. ";"
                if cancelEnabled then itm.ProgressCancelButton.Text = 'Cancelled' end
            else
                itm.HeaderLabel.Text = 'Processing Complete!'
                itm.CurrentItemLabel.Text = string.format('Processed %d item%s', total, total == 1 and '' or 's')
                -- Change progress bar to green on completion
                itm.ProgressBarLabel.StyleSheet = "color: " .. C.accentSuccess .. ";"
            end
            if cancelEnabled then itm.ProgressCancelButton.Enabled = false end
        elseif cancelRequested then
            -- Keep the Cancel handler's feedback until the loop breaks
            itm.HeaderLabel.Text = 'Cancelling...'
            itm.CurrentItemLabel.Text = itemName or 'Finishing current item...'
            itm.ProgressBarLabel.StyleSheet = "color: " .. C.accentProgress .. ";"
        else
            itm.HeaderLabel.Text = 'Processing...'
            itm.CurrentItemLabel.Text = itemName or 'Working...'
            -- Blue progress bar during processing
            itm.ProgressBarLabel.StyleSheet = "color: " .. C.accentProgress .. ";"
        end

        itm.ProgressBarLabel.Text = progressBar
        itm.ProgressTextLabel.Text = string.format('%d%% (%d / %d)', percentage, current, total)

        -- Log status message to console if provided
        if statusMessage then
            print(statusMessage)
        end
    end

    -- Hide the window
    function progressObj.hide()
        if progressObj.window and progressObj.isVisible then
            progressObj.window:Hide()
            progressObj.isVisible = false
        end
    end

    -- True once the user clicked Cancel or closed the progress window (X).
    -- The flag is only refreshed by update()'s event pump, so poll it right
    -- after an update call (the standard loop shape does this naturally).
    -- Always false when options.cancellable was not set or StepLoop is
    -- unavailable on this build.
    function progressObj.isCancelled()
        return cancelRequested
    end

    return progressObj
end

-- ============================================================================
-- DIALOG BUSY STATE
-- ============================================================================

-- Grey out and lock a persistent dialog while a blocking handler runs.
-- Disables the standard 'DialogContent' root group (all production dialogs
-- share it), which cascades to every control including the footer link.
-- Children that were EXPLICITLY disabled (e.g. settings_sync's
-- ApplyButton before the first Copy) keep their own state across the cycle:
-- re-enabling the parent only lifts the implicit parent disable.
-- Not covered: the title-bar X. A mid-run close click queues and fires the
-- Close handler after processing returns, which is safe (Close handlers only
-- save prefs / ExitLoop).
-- Repaint: property assignment paints synchronously even while the event
-- loop is blocked (same mechanism as progress window updates). If a platform
-- ever fails to repaint the greyed state, re-assign the window's StyleSheet
-- (dialog.StyleSheet = getStyles().WINDOW) right after flipping Enabled to
-- force a paint.
function UI.setDialogBusy(dialog, busy)
    local content = dialog:Find("DialogContent")
    if not content then
        return nil, "setDialogBusy: no 'DialogContent' group in dialog"
    end
    content.Enabled = not busy
    return true, nil
end

-- Run fn(...) with the dialog busy-disabled, always re-enabling afterward -
-- a Lua error mid-processing must not leave the dialog permanently dead.
-- The error is printed and returned as (nil, err), never rethrown into the
-- event loop. fn's own return values are discarded (wrapped handlers are
-- procedures that print their own summaries).
function UI.runWithDialogBusy(dialog, fn, ...)
    UI.setDialogBusy(dialog, true)
    local ok, err = pcall(fn, ...)
    UI.setDialogBusy(dialog, false)
    if not ok then
        print("Error: " .. tostring(err))
        return nil, tostring(err)
    end
    return true, nil
end

-- ============================================================================
-- RETURN MODULE
-- ============================================================================

return UI